@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #F02D00;
  --primary-hover: #D02700;
  --dark: #171717;
  --white: #FFFFFF;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-500: #6B7280;
  --gray-800: #1F2937;
  --font-sans: 'Inter', sans-serif;
  --border-radius: 8px;
  --transition: all 0.3s ease;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  color: var(--dark);
  background-color: var(--white);
  line-height: 1.5;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Utilities */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 24px;
  border-radius: var(--border-radius);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  border: none;
  text-align: center;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-outline {
  background-color: transparent;
  border: 1px solid var(--gray-300);
  color: var(--dark);
}

.btn-outline:hover {
  border-color: var(--dark);
}

.text-primary { color: var(--primary); }
.text-gray { color: var(--gray-500); }
.font-bold { font-weight: 700; }
.text-sm { font-size: 0.875rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }
.text-2xl { font-size: 1.5rem; }
.text-3xl { font-size: 1.875rem; }
.text-4xl { font-size: 2.25rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.mt-8 { margin-top: 2rem; }
.py-12 { padding-top: 3rem; padding-bottom: 3rem; }
.py-20 { padding-top: 5rem; padding-bottom: 5rem; }
.flex { display: flex; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }
.grid { display: grid; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }

/* Promo Banner */
.promo-banner {
  background-color: var(--dark);
  color: var(--white);
  padding: 12px 24px;
  text-align: center;
  position: relative;
  font-weight: 500;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
}

.promo-banner .close-btn {
  position: absolute;
  right: 24px;
  background: none;
  border: none;
  color: var(--gray-300);
  cursor: pointer;
  font-size: 20px;
}

/* Header */
.header {
  border-bottom: 1px solid var(--gray-200);
  background-color: var(--white);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 72px;
}

.logo {
  font-size: 24px;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
}

.nav-links {
  display: flex;
  gap: 24px;
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--primary);
}

.search-bar {
  flex: 1;
  max-width: 400px;
  margin: 0 24px;
  position: relative;
}

.search-bar input {
  width: 100%;
  padding: 10px 16px 10px 40px;
  border-radius: 999px;
  border: 1px solid var(--gray-300);
  background-color: var(--gray-100);
  outline: none;
}

.search-bar input:focus {
  border-color: var(--dark);
  background-color: var(--white);
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-500);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  overflow: hidden;
  background-color: var(--gray-100);
  padding: 60px 0;
}

.carousel-inner {
  display: flex;
  transition: transform 0.5s ease-in-out;
}

.carousel-item {
  min-width: 100%;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

.carousel-content {
  flex: 1;
  max-width: 600px;
}

.carousel-image {
  flex: 1;
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
  background-color: var(--gray-300);
}

.badge {
  display: inline-block;
  background-color: var(--dark);
  color: var(--white);
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 700;
  border-radius: 4px;
  margin-bottom: 16px;
}

.badge.primary {
  background-color: var(--primary);
}

.price-block {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 24px 0;
}

.price-sale {
  font-size: 32px;
  font-weight: 800;
}

.price-original {
  text-decoration: line-through;
  color: var(--gray-500);
  font-size: 18px;
}

.carousel-controls {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  transform: translateY(-50%);
  display: flex;
  justify-content: space-between;
  padding: 0 24px;
  pointer-events: none;
}

.carousel-controls button {
  pointer-events: auto;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.carousel-controls button:hover {
  background-color: var(--gray-100);
}

/* Course Cards */
.course-card {
  border: 1px solid var(--gray-200);
  border-radius: var(--border-radius);
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  background-color: var(--white);
}

.course-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.course-thumbnail {
  aspect-ratio: 16/9;
  background-color: var(--gray-200);
  position: relative;
}

.course-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.course-badge-overlay {
  position: absolute;
  top: 8px;
  left: 8px;
}

.course-content {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.course-title {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 4px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-instructor {
  font-size: 14px;
  color: var(--gray-500);
  margin-bottom: 12px;
}

.course-stats {
  font-size: 13px;
  color: var(--gray-500);
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.course-rating {
  color: #F59E0B;
  font-weight: 600;
}

.course-footer {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}

.course-price {
  font-size: 20px;
  font-weight: 800;
}

/* Value Props */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.value-prop-item h3 {
  font-size: 18px;
  margin-bottom: 8px;
}

.value-prop-item p {
  color: var(--gray-500);
  font-size: 15px;
}

/* Footer */
.footer {
  background-color: var(--dark);
  color: var(--white);
  padding: 64px 0 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
  color: var(--gray-300);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-col a {
  color: var(--gray-300);
  font-size: 14px;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid var(--gray-800);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 14px;
  color: var(--gray-500);
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

/* Courses Sidebar */
.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 40px 0;
}

.sidebar h3 {
  font-size: 16px;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--gray-200);
}

.sidebar ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 32px;
}

.sidebar a {
  color: var(--gray-500);
  font-size: 14px;
}

.sidebar a:hover, .sidebar a.active {
  color: var(--dark);
  font-weight: 600;
}

/* Masonry Projects */
.projects-header {
  padding: 40px 0;
  border-bottom: 1px solid var(--gray-200);
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
}

.filter-select {
  padding: 8px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--border-radius);
  background-color: var(--white);
  font-family: inherit;
  font-size: 14px;
  cursor: pointer;
}

.masonry-grid {
  column-count: 3;
  column-gap: 24px;
  padding: 40px 0;
}

.project-card {
  break-inside: avoid;
  margin-bottom: 24px;
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  background-color: var(--white);
}

.project-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.project-img {
  width: 100%;
  display: block;
}

.project-info {
  padding: 16px;
}

.project-title {
  font-weight: 700;
  margin-bottom: 4px;
}

.project-author {
  font-size: 14px;
  color: var(--gray-500);
  margin-bottom: 12px;
}

.project-stats {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--gray-500);
}

/* Plus Pricing */
.plus-hero {
  text-align: center;
  padding: 80px 0;
  background-color: var(--gray-100);
}

.pricing-toggle {
  display: inline-flex;
  background-color: var(--gray-200);
  border-radius: 999px;
  padding: 4px;
  margin: 32px 0;
}

.pricing-toggle button {
  padding: 12px 32px;
  border-radius: 999px;
  border: none;
  background: transparent;
  font-weight: 600;
  font-size: 16px;
  cursor: pointer;
  transition: var(--transition);
}

.pricing-toggle button.active {
  background-color: var(--white);
  box-shadow: var(--shadow-sm);
}

.pricing-card {
  max-width: 480px;
  margin: 0 auto;
  background-color: var(--white);
  border-radius: 16px;
  padding: 40px;
  box-shadow: var(--shadow-lg);
  text-align: left;
}

.pricing-amount {
  font-size: 48px;
  font-weight: 800;
  margin-bottom: 8px;
}

.pricing-features {
  margin: 32px 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* FAQ Accordion */
.faq-section {
  max-width: 800px;
  margin: 80px auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  background: none;
  border: none;
  font-size: 18px;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-answer p {
  padding-bottom: 24px;
  color: var(--gray-500);
}

/* Login Form */
.login-page {
  display: flex;
  min-height: 100vh;
}

.login-image {
  flex: 1;
  background-color: var(--gray-200);
  background-image: url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2000&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
  display: none;
}

@media (min-width: 1024px) {
  .login-image {
    display: block;
  }
}

.login-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 600px;
  margin: 0 auto;
  padding: 40px;
}

.login-form {
  width: 100%;
  max-width: 400px;
  margin: 0 auto;
}

.form-group {
  margin-bottom: 20px;
}

.form-label {
  display: block;
  font-weight: 500;
  margin-bottom: 8px;
}

.form-input {
  width: 100%;
  padding: 12px 16px;
  border: 1px solid var(--gray-300);
  border-radius: var(--border-radius);
  font-family: inherit;
  font-size: 16px;
}

.form-input:focus {
  outline: none;
  border-color: var(--dark);
}

.password-input-wrapper {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--gray-500);
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 32px;
}

.btn-social {
  background-color: var(--white);
  border: 1px solid var(--gray-300);
  color: var(--dark);
  font-weight: 500;
}

.btn-social:hover {
  background-color: var(--gray-100);
}

.divider {
  display: flex;
  align-items: center;
  text-align: center;
  margin: 24px 0;
  color: var(--gray-500);
  font-size: 14px;
}

.divider::before, .divider::after {
  content: '';
  flex: 1;
  border-bottom: 1px solid var(--gray-300);
}

.divider:not(:empty)::before {
  margin-right: .25em;
}

.divider:not(:empty)::after {
  margin-left: .25em;
}

/* Responsive */
@media (max-width: 768px) {
  .grid-cols-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-cols-3 { grid-template-columns: 1fr; }

  .courses-layout {
    grid-template-columns: 1fr;
  }

  .masonry-grid {
    column-count: 1;
  }

  .carousel-item {
    flex-direction: column-reverse;
  }

  .carousel-image {
    width: 100%;
  }

  .header .nav-links, .header .search-bar {
    display: none;
  }

  /* Mobile footer accordion */
  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    margin-bottom: 0;
    padding: 16px 0;
    border-bottom: 1px solid var(--gray-800);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    padding-top: 0;
  }

  .footer-col.active ul {
    max-height: 500px;
    padding-top: 16px;
    padding-bottom: 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Promo banner toggle
  const promoBanner = document.querySelector('.promo-banner');
  const closePromoBtn = document.querySelector('.promo-banner .close-btn');
  if (closePromoBtn && promoBanner) {
    closePromoBtn.addEventListener('click', () => {
      promoBanner.style.display = 'none';
    });
  }

  // Mobile Footer Accordion
  const footerCols = document.querySelectorAll('.footer-col h4');
  footerCols.forEach(col => {
    col.addEventListener('click', () => {
      if (window.innerWidth <= 768) {
        const parent = col.parentElement;
        parent.classList.toggle('active');
      }
    });
  });

  // Hero Carousel
  const heroInner = document.querySelector('.hero-carousel .carousel-inner');
  const heroPrev = document.querySelector('.hero-carousel .prev-btn');
  const heroNext = document.querySelector('.hero-carousel .next-btn');

  if (heroInner && heroPrev && heroNext) {
    let currentSlide = 0;
    const slidesCount = heroInner.children.length;

    const updateCarousel = () => {
      heroInner.style.transform = `translateX(-${currentSlide * 100}%)`;
    };

    heroNext.addEventListener('click', () => {
      currentSlide = (currentSlide + 1) % slidesCount;
      updateCarousel();
    });

    heroPrev.addEventListener('click', () => {
      currentSlide = (currentSlide - 1 + slidesCount) % slidesCount;
      updateCarousel();
    });
  }

  // Course / Project Sorting & Filtering (Mock functionality)
  const filterSelects = document.querySelectorAll('.filter-select');
  if (filterSelects.length > 0) {
    filterSelects.forEach(select => {
      select.addEventListener('change', (e) => {
        // Mocking the visual update
        const grid = document.querySelector('.masonry-grid') || document.querySelector('.grid-cols-4');
        if (grid) {
          grid.style.opacity = '0.5';
          setTimeout(() => {
            grid.style.opacity = '1';
            // In a real app, this would re-render or re-order elements
          }, 300);
        }
      });
    });
  }

  // Courses Sidebar Filtering
  const sidebarLinks = document.querySelectorAll('.sidebar a');
  sidebarLinks.forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      sidebarLinks.forEach(l => l.classList.remove('active', 'font-bold', 'text-dark'));
      link.classList.add('active', 'font-bold', 'text-dark');

      const grid = document.querySelector('.courses-layout .grid');
      if (grid) {
        grid.style.opacity = '0.5';
        setTimeout(() => {
          grid.style.opacity = '1';
        }, 300);
      }
    });
  });

  // Plus Pricing Tabs
  const pricingToggleBtns = document.querySelectorAll('.pricing-toggle button');
  if (pricingToggleBtns.length > 0) {
    pricingToggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        pricingToggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const type = btn.dataset.type;
        const priceElement = document.querySelector('.pricing-amount');
        const billedElement = document.querySelector('.pricing-billed');
        const creditsElement = document.querySelector('.pricing-credits');
        const savingsBadge = document.querySelector('.savings-badge');

        if (type === 'yearly') {
          priceElement.innerHTML = '$14.59<span class="text-xl font-normal text-gray">/month</span>';
          billedElement.textContent = 'Billed as $174.50/year';
          creditsElement.textContent = '12 Plus credits every year';
          if(savingsBadge) savingsBadge.style.display = 'inline-block';
        } else {
          priceElement.innerHTML = '$33.90<span class="text-xl font-normal text-gray">/month</span>';
          billedElement.textContent = 'Billed as $33.90/month';
          creditsElement.textContent = '1 Plus credit every month';
          if(savingsBadge) savingsBadge.style.display = 'none';
        }
      });
    });
  }

  // Plus FAQ Accordion
  const faqQuestions = document.querySelectorAll('.faq-question');
  faqQuestions.forEach(question => {
    question.addEventListener('click', () => {
      const answer = question.nextElementSibling;
      const isOpen = answer.style.maxHeight;

      // Close all other answers
      document.querySelectorAll('.faq-answer').forEach(ans => {
        ans.style.maxHeight = null;
      });
      document.querySelectorAll('.faq-question span:last-child').forEach(icon => {
        icon.textContent = '+';
      });

      if (!isOpen) {
        answer.style.maxHeight = answer.scrollHeight + 'px';
        question.querySelector('span:last-child').textContent = '-';
      }
    });
  });

  // Login Password Toggle
  const togglePassword = document.querySelector('.password-toggle');
  const passwordInput = document.querySelector('input[type="password"]');
  if (togglePassword && passwordInput) {
    togglePassword.addEventListener('click', () => {
      const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
      passwordInput.setAttribute('type', type);
      togglePassword.textContent = type === 'password' ? '👁️' : '👁️‍🗨️'; // basic icon swap
    });
  }
});
